import { Field, ProfilePatch } from './types';

const MAX_DISPLAY_NAME = 40;
const MAX_TAGS = 5;
const MAX_TAG_LENGTH = 12;

function invalid(): never {
  throw new Error('invalid profile');
}

function hasOwn(target: object, key: PropertyKey): boolean {
  return Object.prototype.hasOwnProperty.call(target, key);
}

// Reads an own data property; accessors are rejected so no user code runs.
function dataValue(target: object, key: PropertyKey): unknown {
  const descriptor = Object.getOwnPropertyDescriptor(target, key);
  if (!descriptor || !('value' in descriptor)) return invalid();
  return descriptor.value;
}

function parseDisplayName(value: unknown): Field<string | null> {
  if (value === null) return { kind: 'set', value: null };
  if (typeof value !== 'string') return invalid();
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > MAX_DISPLAY_NAME) return invalid();
  return { kind: 'set', value: trimmed };
}

function parseTags(value: unknown): Field<string[]> {
  if (value === null) return { kind: 'set', value: [] };
  if (!Array.isArray(value)) return invalid();
  const length = value.length;
  if (length > MAX_TAGS) return invalid();
  // Only the indices 0..length-1 plus "length" may be own keys: no holes, no extras.
  if (Reflect.ownKeys(value).length !== length + 1) return invalid();
  const tags: string[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < length; i++) {
    if (!hasOwn(value, i)) return invalid();
    const item = dataValue(value, i);
    if (typeof item !== 'string') return invalid();
    const trimmed = item.trim();
    if (trimmed.length < 1 || trimmed.length > MAX_TAG_LENGTH) return invalid();
    if (seen.has(trimmed)) return invalid();
    seen.add(trimmed);
    tags.push(trimmed);
  }
  return { kind: 'set', value: tags };
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) return invalid();
  const proto: unknown = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) return invalid();
  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') return invalid();
  }
  let displayName: Field<string | null> = { kind: 'keep' };
  let tags: Field<string[]> = { kind: 'keep' };
  if (hasOwn(input, 'displayName')) displayName = parseDisplayName(dataValue(input, 'displayName'));
  if (hasOwn(input, 'tags')) tags = parseTags(dataValue(input, 'tags'));
  return { displayName, tags };
}
