// PATCH contract
{
  const { ProfileService } = require('../.build/service');
  const fresh = () => new ProfileService({ displayName: 'before', tags: ['old'] });
  const snapshot = (s) => JSON.parse(JSON.stringify(s.profile));

  // empty object is a no-op
  let s = fresh();
  assert.deepEqual(s.patch({}), { displayName: 'before', tags: ['old'] });

  // displayName: trimmed, null clears
  s = fresh();
  assert.equal(s.patch({ displayName: '  Ann  ' }).displayName, 'Ann');
  assert.equal(s.patch({ displayName: null }).displayName, null);
  assert.equal(fresh().patch({ displayName: 'a'.repeat(40) }).displayName, 'a'.repeat(40));
  for (const bad of ['', '   ', 'a'.repeat(41), 0, 1, undefined, true, {}, []]) {
    s = fresh();
    assert.throws(() => s.patch({ displayName: bad }), /invalid profile/);
    assert.deepEqual(snapshot(s), { displayName: 'before', tags: ['old'] });
  }

  // tags: null or [] clears; trimmed; distinct after trim; max 5; max 12 chars; nonempty
  assert.deepEqual(fresh().patch({ tags: null }).tags, []);
  assert.deepEqual(fresh().patch({ tags: [] }).tags, []);
  assert.deepEqual(fresh().patch({ tags: [' a ', 'b', 'c', 'd', 'e'] }).tags, ['a', 'b', 'c', 'd', 'e']);
  assert.deepEqual(fresh().patch({ tags: ['x'.repeat(12)] }).tags, ['x'.repeat(12)]);
  const badTags = [
    ['a', 'a'], [' a', 'a '], ['a', 'b', 'c', 'd', 'e', 'f'], ['x'.repeat(13)],
    [''], ['   '], [1], [null], 'a', { 0: 'a', length: 1 }, [, 'a'],
  ];
  for (const bad of badTags) {
    s = fresh();
    assert.throws(() => s.patch({ tags: bad }), /invalid profile/);
    assert.deepEqual(snapshot(s), { displayName: 'before', tags: ['old'] });
  }

  // unknown keys, non-objects, arrays, null, bad prototypes all rejected
  for (const bad of [{ extra: 1 }, { displayName: 'ok', x: 1 }, null, 'str', 1, [], [{}],
    Object.create({ displayName: 'inherited' })]) {
    s = fresh();
    assert.throws(() => s.patch(bad), /invalid profile/);
    assert.deepEqual(snapshot(s), { displayName: 'before', tags: ['old'] });
  }
  // null-prototype object is accepted
  const np = Object.create(null); np.displayName = 'Nul';
  assert.equal(fresh().patch(np).displayName, 'Nul');

  // input not mutated; caller's tags array not stored
  const input = { tags: ['p', 'q'] };
  s = fresh();
  const result = s.patch(input);
  assert.deepEqual(input, { tags: ['p', 'q'] });
  assert.notEqual(result.tags, input.tags);
  assert.notEqual(s.profile.tags, input.tags);
}
